private val nextId = AtomicLong()
suspend fun call(bus: SendChannel<Envelope>, payload: Request): Reply =
    withTimeout(5_000) {
        val reply = CompletableDeferred<Reply>()      // per-request reply channel
        bus.send(Envelope("req-${nextId.incrementAndGet()}", payload, reply))
        reply.await()                                 // cancellation propagates
    }
